import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{o,c as d,a8 as a}from"./chunks/vendor-scheduler.BuXoCeGx.js";const m=JSON.parse('{"title":"可访问性约定","description":"当前组件库在键盘操作、焦点管理和语义角色上的统一约定。","frontmatter":{"title":"可访问性约定","description":"当前组件库在键盘操作、焦点管理和语义角色上的统一约定。","outline":"deep"},"headers":[],"relativePath":"guide/accessibility.md","filePath":"guide/accessibility.md","lastUpdated":1774557523000}'),r={name:"guide/accessibility.md"};function c(l,e,i,n,s,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="可访问性约定" tabindex="-1">可访问性约定 <a class="header-anchor" href="#可访问性约定" aria-label="Permalink to &quot;可访问性约定&quot;">​</a></h1><p>这页先把组件库目前的无障碍基线讲清楚。它描述的是跨组件契约，而不是某一个组件的局部实现。</p><p class="xy-section-lead"> 如果你要判断一套组件能不能稳定接入后台项目，除了看 API，还要先看键盘路径、焦点管理和语义角色是不是一致。这页就是这条基线。 </p><h2 id="键盘约定" tabindex="-1">键盘约定 <a class="header-anchor" href="#键盘约定" aria-label="Permalink to &quot;键盘约定&quot;">​</a></h2><div class="xy-vp-table"><table><thead><tr><th>组件</th><th>当前约定</th></tr></thead><tbody><tr><td><code>Tabs</code></td><td><code>ArrowLeft / ArrowRight / ArrowUp / ArrowDown</code> 切换，<code>Home / End</code> 快速跳到首尾可用项</td></tr><tr><td><code>Select</code></td><td><code>ArrowUp / ArrowDown</code> 移动高亮，<code>Enter / Space</code> 选择，<code>Escape</code> 关闭并回到触发器</td></tr><tr><td><code>Dropdown</code></td><td><code>ArrowUp / ArrowDown / Home / End</code> 遍历菜单项，<code>Enter / Space</code> 选择</td></tr><tr><td><code>Collapse</code></td><td><code>Enter / Space</code> 切换当前面板</td></tr><tr><td><code>Dialog</code></td><td>打开后焦点带入弹层，<code>Tab / Shift+Tab</code> 在内部循环，<code>Escape</code> 关闭</td></tr><tr><td><code>Drawer</code></td><td>与 <code>Dialog</code> 保持一致：焦点带入、焦点恢复、<code>Escape</code> 关闭</td></tr><tr><td><code>Tooltip</code></td><td>支持 <code>focus</code> 打开，<code>Escape</code> 关闭</td></tr><tr><td><code>Popover</code></td><td><code>Enter / Space</code> 打开，<code>Escape</code> 和外部点击关闭</td></tr></tbody></table></div><h2 id="焦点管理约定" tabindex="-1">焦点管理约定 <a class="header-anchor" href="#焦点管理约定" aria-label="Permalink to &quot;焦点管理约定&quot;">​</a></h2><ul><li>模态类组件默认在打开后把焦点带入内部。</li><li>模态类组件关闭后，焦点恢复到触发元素。</li><li>组合框和菜单关闭后，焦点回到触发器，而不是丢到页面根部。</li><li>多层 overlay 并存时，只有最上层响应该轮 <code>Escape</code> 或外部点击关闭。</li></ul><h2 id="语义角色约定" tabindex="-1">语义角色约定 <a class="header-anchor" href="#语义角色约定" aria-label="Permalink to &quot;语义角色约定&quot;">​</a></h2><div class="xy-vp-table"><table><thead><tr><th>组件模式</th><th>当前语义</th></tr></thead><tbody><tr><td>Tabs</td><td><code>tablist / tab / tabpanel</code></td></tr><tr><td>Select</td><td><code>combobox / listbox / option</code></td></tr><tr><td>Dropdown</td><td><code>menu / menuitem</code></td></tr><tr><td>Collapse</td><td><code>button / region</code></td></tr><tr><td>Tooltip</td><td><code>tooltip</code></td></tr><tr><td>Dialog / Drawer</td><td><code>dialog</code> + <code>aria-modal=&quot;true&quot;</code></td></tr><tr><td>Popover</td><td><code>dialog</code>，但不强制模态</td></tr></tbody></table></div><h2 id="文档使用方式" tabindex="-1">文档使用方式 <a class="header-anchor" href="#文档使用方式" aria-label="Permalink to &quot;文档使用方式&quot;">​</a></h2><ul><li>想看单组件 Props、Events、Slots：去对应组件页</li><li>想看多组件如何组合成页面：看场景页和示例页</li><li>想确认当前库的无障碍基线：先看本页</li></ul><h2 id="对应组件页" tabindex="-1">对应组件页 <a class="header-anchor" href="#对应组件页" aria-label="Permalink to &quot;对应组件页&quot;">​</a></h2><ul><li><a href="/components/select">Select 选择器</a></li><li><a href="/components/tabs">Tabs 标签页</a></li><li><a href="/components/collapse">Collapse 折叠面板</a></li><li><a href="/components/tooltip">Tooltip 文字提示</a></li><li><a href="/components/dialog">Dialog 对话框</a></li><li><a href="/components/dropdown">Dropdown 下拉菜单</a></li><li><a href="/components/popover">Popover 气泡卡片</a></li><li><a href="/components/drawer">Drawer 抽屉</a></li></ul><h2 id="推荐怎么继续读" tabindex="-1">推荐怎么继续读 <a class="header-anchor" href="#推荐怎么继续读" aria-label="Permalink to &quot;推荐怎么继续读&quot;">​</a></h2><ol><li>如果你先关心单个组件的键盘路径，优先看 <a href="/components/select">Select 选择器</a>、<a href="/components/tabs">Tabs 标签页</a>、<a href="/components/dropdown">Dropdown 下拉菜单</a>。</li><li>如果你更关心浮层类组件的焦点管理，继续看 <a href="/components/dialog">Dialog 对话框</a>、<a href="/components/drawer">Drawer 抽屉</a>、<a href="/components/popover">Popover 气泡卡片</a>。</li><li>如果你想看这些能力如何放回真实页面，再去看 <a href="/examples/admin">管理后台闭环示例</a>。</li></ol>',15)])])}const u=t(r,[["render",c]]);export{m as __pageData,u as default};
